using System.Security.Claims;
using System.Text;
using GameHub.Data;
using GameHub.Filters;
using GameHub.Helpers;
using GameHub.Models.Entities;
using GameHub.Models.Enums;
using GameHub.Models.ViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;

namespace GameHub.Controllers
{
    [GameHubAuthorize(UserRole.SuperAdmin, UserRole.Admin, UserRole.FinanceManager, UserRole.BookingManager, UserRole.CourtManager, UserRole.StaffManager, UserRole.Receptionist, UserRole.Viewer)]
    [ValidateActiveUser]
    public class ReportsController : Controller
    {
        private static readonly int[] PageSizes = [10, 25, 50];
        private readonly ApplicationDbContext _db;
        public ReportsController(ApplicationDbContext db) => _db = db;

        [HttpGet("/Reports")]
        public async Task<IActionResult> Index([FromQuery] ReportFilterViewModel filter) => View(await BuildOverviewAsync(filter));

        [HttpGet("/Reports/Sales")]
        public async Task<IActionResult> Sales([FromQuery] ReportFilterViewModel filter) => await ReportResult("sales", filter);

        [HttpGet("/Reports/Invoices")]
        public async Task<IActionResult> Invoices([FromQuery] ReportFilterViewModel filter) => await ReportResult("invoices", filter);

        [HttpGet("/Reports/Bookings")]
        public async Task<IActionResult> Bookings([FromQuery] ReportFilterViewModel filter) => await ReportResult("bookings", filter);

        [HttpGet("/Reports/Customers")]
        public async Task<IActionResult> Customers([FromQuery] ReportFilterViewModel filter) => await ReportResult("customers", filter);

        [HttpGet("/Reports/Memberships")]
        public async Task<IActionResult> Memberships([FromQuery] ReportFilterViewModel filter) => await ReportResult("memberships", filter);

        [HttpGet("/Reports/CRM")]
        public async Task<IActionResult> CRM([FromQuery] ReportFilterViewModel filter) => await ReportResult("crm", filter);

        [HttpGet("/Reports/Utilization")]
        public async Task<IActionResult> Utilization([FromQuery] ReportFilterViewModel filter) => await ReportResult("utilization", filter);

        [HttpGet("/Reports/Revenue")]
        public async Task<IActionResult> Revenue([FromQuery] ReportFilterViewModel filter) => await ReportResult("revenue", filter);

        [HttpGet("/Reports/Exports")]
        public async Task<IActionResult> Exports() => View(await BasePage("exports", new ReportFilterViewModel()));

        [HttpGet("/Reports/Export")]
        public async Task<IActionResult> Export(string report, string format, [FromQuery] ReportFilterViewModel filter)
        {
            report = (report ?? string.Empty).Trim().ToLowerInvariant();
            if (!CanAccessReport(report) || format is not ("csv" or "excel")) return RedirectToAction("NotFound", "Error");
            filter.Page = 1; filter.PageSize = 10000;
            var model = await BuildDetailedAsync(report, filter, true);
            var generatedBy = User.FindFirstValue(ClaimTypes.Name) ?? "GameHub User";
            return format == "csv" ? Csv(model, generatedBy) : Excel(model, generatedBy);
        }

        private async Task<IActionResult> ReportResult(string report, ReportFilterViewModel filter)
        {
            if (!CanAccessReport(report)) return RedirectToAction("NotFound", "Error");
            return View("Report", await BuildDetailedAsync(report, filter));
        }

        private async Task<ReportPageViewModel> BuildOverviewAsync(ReportFilterViewModel filter)
        {
            var model = await BasePage("overview", filter); model.IsOverview = true; model.Title = "Reports & Analytics"; model.Description = "A unified view of GameHub commercial performance, bookings, customers and arena utilization.";
            var (start, end) = (model.RangeStart, model.RangeEnd); var from = start.ToDateTime(TimeOnly.MinValue); var until = end.AddDays(1).ToDateTime(TimeOnly.MinValue);
            var bookings = ApplyBookingFilters(_db.Bookings.AsNoTracking().Where(x => x.IsActive && x.BookingDate >= start && x.BookingDate <= end), filter);
            var invoices = _db.SalesInvoices.AsNoTracking().Where(x => x.IsActive && x.InvoiceDate >= start && x.InvoiceDate <= end);
            var payments = _db.Payments.AsNoTracking().Where(x => x.IsActive && x.PaymentDate >= start && x.PaymentDate <= end);
            if (filter.CustomerId.HasValue) { invoices = invoices.Where(x => x.CustomerId == filter.CustomerId); payments = payments.Where(x => x.CustomerId == filter.CustomerId); }
            if (filter.OwnerId.HasValue) invoices = invoices.Where(x => x.AssignedToUserId == filter.OwnerId);
            var totalRevenue = await invoices.SumAsync(x => (decimal?)x.GrandTotal) ?? 0; var collected = await payments.SumAsync(x => (decimal?)x.Amount) ?? 0; var outstanding = await invoices.SumAsync(x => (decimal?)x.OutstandingAmount) ?? 0; var bookingCount = await bookings.CountAsync(); var bookingValue = await bookings.SumAsync(x => (decimal?)x.TotalAmount) ?? 0;
            var activeCustomers = await _db.Customers.AsNoTracking().CountAsync(x => x.IsActive); var activeMemberships = await _db.CustomerMemberships.AsNoTracking().CountAsync(x => x.IsActive && x.Status == MembershipStatus.Active && x.ExpiryDate >= DateOnly.FromDateTime(DateTime.UtcNow));
            var bookedMinutes = await bookings.SumAsync(x => (int?)x.DurationMinutes) ?? 0; var activeCourtCount = Math.Max(1, await _db.Courts.AsNoTracking().CountAsync(x => x.IsActive)); var settings = await Settings(); var dailyMinutes = Math.Max(1, (int)(settings.ClosingTime - settings.OpeningTime).TotalMinutes); var availableMinutes = activeCourtCount * (end.DayNumber - start.DayNumber + 1) * dailyMinutes; var utilization = Math.Min(100m, availableMinutes == 0 ? 0 : bookedMinutes * 100m / availableMinutes);
            model.Kpis = [Kpi("Total Revenue", Money(model,totalRevenue), "Invoices raised", "bi-graph-up-arrow"),Kpi("Collected Revenue", Money(model,collected), "Recorded invoice payments", "bi-wallet2","positive"),Kpi("Outstanding Amount", Money(model,outstanding), "Open receivables", "bi-exclamation-circle","warning"),Kpi("Total Bookings", bookingCount.ToString("N0"), "Bookings in scope", "bi-calendar-check"),Kpi("Active Customers", activeCustomers.ToString("N0"), "Customer master", "bi-people"),Kpi("Active Memberships", activeMemberships.ToString("N0"), "Current subscriptions", "bi-person-badge"),Kpi("Average Booking Value", Money(model,bookingCount == 0 ? 0 : bookingValue/bookingCount), "Per booking", "bi-cash-coin"),Kpi("Court Utilization", $"{utilization:N1}%", "Booked vs available hours", "bi-grid-3x3-gap")];
            if (!model.ShowFinancials) model.Kpis = model.Kpis.Select(x => x.Label.Contains("Revenue") || x.Label.Contains("Amount") || x.Label.Contains("Value") ? Kpi(x.Label,"Restricted","Finance role required",x.Icon) : x).ToList();
            var revenueTrend = await payments.GroupBy(x => x.PaymentDate).Select(g => new { Date=g.Key, Value=g.Sum(x=>x.Amount) }).OrderBy(x=>x.Date).ToListAsync(); var bookingTrend = await bookings.GroupBy(x=>x.BookingDate).Select(g=>new{Date=g.Key,Value=g.Count()}).OrderBy(x=>x.Date).ToListAsync();
            var methods = await payments.GroupBy(x=>x.PaymentMethod).Select(g=>new{Name=g.Key.ToString(),Value=g.Sum(x=>x.Amount)}).OrderByDescending(x=>x.Value).ToListAsync(); var bySport = await bookings.GroupBy(x=>x.Sport.Name).Select(g=>new{Name=g.Key,Value=g.Sum(x=>x.PaidAmount)}).OrderByDescending(x=>x.Value).Take(6).ToListAsync(); var byFacility = await bookings.GroupBy(x=>x.Facility.Name).Select(g=>new{Name=g.Key,Value=g.Sum(x=>x.PaidAmount)}).OrderByDescending(x=>x.Value).Take(6).ToListAsync(); var invoiceStatuses = await invoices.GroupBy(x=>x.Status).Select(g=>new{Name=g.Key.ToString(),Value=g.Count()}).ToListAsync(); var bookingStatuses = await bookings.GroupBy(x=>x.Status).Select(g=>new{Name=g.Key.ToString(),Value=g.Count()}).ToListAsync(); var newCustomers = await _db.Customers.AsNoTracking().CountAsync(x=>x.CreatedAt>=from&&x.CreatedAt<until); var returning = await bookings.Where(x=>x.Customer.CreatedAt<from).Select(x=>x.CustomerId).Distinct().CountAsync();
            model.Charts = [Chart("revenueTrend","Revenue Trend","Recorded payments by day","line",revenueTrend.Select(x=>x.Date.ToString("dd MMM")),revenueTrend.Select(x=>x.Value),true),Chart("bookingTrend","Bookings Trend","Bookings created for each day","line",bookingTrend.Select(x=>x.Date.ToString("dd MMM")),bookingTrend.Select(x=>(decimal)x.Value)),Chart("paymentMethods","Payment Method Distribution","Collected value by method","doughnut",methods.Select(x=>x.Name),methods.Select(x=>x.Value),true),Chart("sportRevenue","Revenue by Sport","Paid booking value","bar",bySport.Select(x=>x.Name),bySport.Select(x=>x.Value),true),Chart("facilityRevenue","Revenue by Facility","Paid booking value","bar",byFacility.Select(x=>x.Name),byFacility.Select(x=>x.Value),true),Chart("invoiceStatus","Invoice Status Distribution","Invoice count by status","doughnut",invoiceStatuses.Select(x=>x.Name),invoiceStatuses.Select(x=>(decimal)x.Value)),Chart("bookingStatus","Booking Status Distribution","Booking count by status","doughnut",bookingStatuses.Select(x=>x.Name),bookingStatuses.Select(x=>(decimal)x.Value)),Chart("customerMix","New vs Returning Customers","Customer activity in scope","doughnut",["New","Returning"],[(decimal)newCustomers,returning])];
            var topSport = bySport.FirstOrDefault(); var topFacility = byFacility.FirstOrDefault(); var topCourt = await bookings.GroupBy(x=>x.Court.Name).Select(g=>new{Name=g.Key,Count=g.Count()}).OrderByDescending(x=>x.Count).FirstOrDefaultAsync(); var topCustomer = await payments.GroupBy(x=>x.Customer.FirstName+" "+x.Customer.LastName).Select(g=>new{Name=g.Key,Value=g.Sum(x=>x.Amount)}).OrderByDescending(x=>x.Value).FirstOrDefaultAsync(); var popularPlan = await _db.CustomerMemberships.AsNoTracking().Where(x=>x.CreatedAt>=from&&x.CreatedAt<until).GroupBy(x=>x.MembershipPlan.Name).Select(g=>new{Name=g.Key,Count=g.Count()}).OrderByDescending(x=>x.Count).FirstOrDefaultAsync(); var leadSource = await _db.Leads.AsNoTracking().Where(x=>x.IsActive&&x.CreatedAt>=from&&x.CreatedAt<until).GroupBy(x=>x.Source).Select(g=>new{Name=g.Key.ToString(),Count=g.Count(x=>x.IsConverted)}).OrderByDescending(x=>x.Count).FirstOrDefaultAsync(); var overdue = await invoices.CountAsync(x=>x.Status==InvoiceStatus.Overdue);
            model.Insights = [Insight("Best-performing sport",topSport?.Name??"No data",topSport==null?"No paid bookings in scope":Money(model,topSport.Value),"bi-trophy"),Insight("Highest-revenue facility",topFacility?.Name??"No data",topFacility==null?"No paid bookings in scope":Money(model,topFacility.Value),"bi-building"),Insight("Most-booked court",topCourt?.Name??"No data",topCourt==null?"No bookings in scope":$"{topCourt.Count:N0} bookings","bi-grid-3x3-gap"),Insight("Top customer",topCustomer?.Name??"No data",topCustomer==null?"No payments in scope":Money(model,topCustomer.Value),"bi-person-star"),Insight("Fastest-growing membership",popularPlan?.Name??"No data",popularPlan==null?"No subscriptions in scope":$"{popularPlan.Count:N0} subscriptions","bi-person-badge"),Insight("Most effective lead source",leadSource?.Name??"No data",leadSource==null?"No converted leads in scope":$"{leadSource.Count:N0} conversions","bi-funnel"),Insight("Overdue invoice risk",$"{overdue:N0} invoices",overdue>0?"Receivables need follow-up":"No overdue invoices in scope","bi-exclamation-triangle",overdue>0?"risk":"positive")];
            model.Modules = Modules(); return model;
        }

        private async Task<ReportPageViewModel> BuildDetailedAsync(string report, ReportFilterViewModel filter, bool export = false)
        {
            var model = await BasePage(report, filter); if (export) { model.PageSize = 10000; model.CurrentPage = 1; }
            return report switch { "sales"=>await SalesReport(model),"invoices"=>await InvoiceReport(model),"bookings"=>await BookingReport(model),"customers"=>await CustomerReport(model),"memberships"=>await MembershipReport(model),"crm"=>await CrmReport(model),"utilization"=>await UtilizationReport(model),"revenue"=>await RevenueReport(model),_=>model };
        }

        private async Task<ReportPageViewModel> SalesReport(ReportPageViewModel m)
        {
            m.Title="Sales Report";m.Description="Quotation and sales-order conversion, approval and value performance.";m.ActionName=nameof(Sales);var from=m.RangeStart.ToDateTime(TimeOnly.MinValue);var until=m.RangeEnd.AddDays(1).ToDateTime(TimeOnly.MinValue);var f=m.Filter;
            var quotes=_db.SalesQuotations.AsNoTracking().Where(x=>x.IsActive&&x.CreatedAt>=from&&x.CreatedAt<until);var orders=_db.SalesOrders.AsNoTracking().Where(x=>x.IsActive&&x.CreatedAt>=from&&x.CreatedAt<until);if(f.CustomerId.HasValue){quotes=quotes.Where(x=>x.CustomerId==f.CustomerId);orders=orders.Where(x=>x.CustomerId==f.CustomerId);}if(f.OwnerId.HasValue){quotes=quotes.Where(x=>x.AssignedToUserId==f.OwnerId);orders=orders.Where(x=>x.AssignedToUserId==f.OwnerId);}if(Enum.TryParse<SalesQuotationStatus>(f.Status,true,out var qs))quotes=quotes.Where(x=>x.Status==qs);if(Enum.TryParse<SalesOrderStatus>(f.Status,true,out var os))orders=orders.Where(x=>x.Status==os);
            var quoteCount=await quotes.CountAsync();var approvedQuotes=await quotes.CountAsync(x=>x.Status==SalesQuotationStatus.Approved||x.Status==SalesQuotationStatus.AcceptedByCustomer||x.Status==SalesQuotationStatus.ConvertedToSalesOrder);var accepted=await quotes.CountAsync(x=>x.Status==SalesQuotationStatus.AcceptedByCustomer||x.Status==SalesQuotationStatus.ConvertedToSalesOrder);var orderCount=await orders.CountAsync();var approvedOrders=await orders.CountAsync(x=>x.ApprovedAt!=null);var ready=await orders.CountAsync(x=>x.Status==SalesOrderStatus.ReadyForInvoice);var quotedValue=await quotes.SumAsync(x=>(decimal?)x.GrandTotal)??0;var orderedValue=await orders.SumAsync(x=>(decimal?)x.GrandTotal)??0;
            m.Kpis=[Kpi("Quotations",quoteCount.ToString("N0"),"Created in scope","bi-file-earmark-text"),Kpi("Approval Rate",Percent(approvedQuotes,quoteCount),"Approved quotations","bi-check2-circle","positive"),Kpi("Acceptance Rate",Percent(accepted,quoteCount),"Customer accepted","bi-person-check"),Kpi("Sales Orders",orderCount.ToString("N0"),"Orders created","bi-bag-check"),Kpi("Conversion Rate",Percent(orderCount,quoteCount),"Quotation to order","bi-arrow-repeat"),Kpi("Approved Orders",approvedOrders.ToString("N0"),"Financially approved","bi-shield-check"),Kpi("Ready for Invoice",ready.ToString("N0"),"Completed order flow","bi-receipt"),Kpi("Total Quoted",Money(m,quotedValue),"Quoted value","bi-cash-stack"),Kpi("Total Ordered",Money(m,orderedValue),"Ordered value","bi-graph-up"),Kpi("Average Order",Money(m,orderCount==0?0:orderedValue/orderCount),"Per sales order","bi-calculator")];
            var quoteRows=quotes.Select(x=>new SalesRaw{Number=x.QuotationNumber,Customer=x.Customer.FirstName+" "+x.Customer.LastName,Type="Quotation",Owner=x.AssignedToUser==null?"Unassigned":x.AssignedToUser.FirstName+" "+x.AssignedToUser.LastName,Status=x.Status.ToString(),Revision=x.RevisionNumber,Date=x.CreatedAt,Total=x.GrandTotal,Conversion=x.SalesOrderCreated?"Converted":"Not converted",Id=x.Id,Kind=0});var orderRows=orders.Select(x=>new SalesRaw{Number=x.SalesOrderNumber,Customer=x.Customer.FirstName+" "+x.Customer.LastName,Type="Sales Order",Owner=x.AssignedToUser==null?"Unassigned":x.AssignedToUser.FirstName+" "+x.AssignedToUser.LastName,Status=x.Status.ToString(),Revision=x.RevisionNumber,Date=x.CreatedAt,Total=x.GrandTotal,Conversion=x.InvoiceCreated?"Invoiced":"Open",Id=x.Id,Kind=1});var combined=quoteRows.Concat(orderRows);m.TotalRecords=await combined.CountAsync();var raw=await combined.OrderByDescending(x=>x.Date).Skip((m.CurrentPage-1)*m.PageSize).Take(m.PageSize).ToListAsync();m.Columns=["Document Number","Customer","Document Type","Owner","Status","Revision","Date","Total","Conversion State"];m.Rows=raw.Select(x=>Row([x.Number,x.Customer,x.Type,x.Owner,x.Status,$"R{x.Revision}",x.Date.ToString("dd MMM yyyy"),Money(m,x.Total),x.Conversion],x.Status,Url.Action(x.Kind==0?"QuotationDetails":"Details",x.Kind==0?"Sales":"SalesOrders",new{id=x.Id}))).ToList();m.Charts=[await StatusChart(quotes,"salesStatus","Quotation Status","Quotation workflow distribution")];m.Insights=[Insight("Key finding",$"{Percent(orderCount,quoteCount)} conversion","Quotation-to-order conversion in scope","bi-lightbulb"),Insight("Risk",$"{quoteCount-approvedQuotes:N0} unapproved","Review quotation approval backlog","bi-exclamation-triangle","risk"),Insight("Recommended action",$"{ready:N0} ready orders","Move fulfilled orders into invoicing","bi-arrow-right-circle")];return Finish(m);
        }

        private async Task<ReportPageViewModel> InvoiceReport(ReportPageViewModel m)
        {
            m.Title="Invoice & Payment Report";m.Description="Receivables, collections, payment behavior and overdue exposure.";m.ActionName=nameof(Invoices);var q=_db.SalesInvoices.AsNoTracking().Where(x=>x.IsActive&&x.InvoiceDate>=m.RangeStart&&x.InvoiceDate<=m.RangeEnd);var f=m.Filter;if(f.CustomerId.HasValue)q=q.Where(x=>x.CustomerId==f.CustomerId);if(f.OwnerId.HasValue)q=q.Where(x=>x.AssignedToUserId==f.OwnerId);if(Enum.TryParse<InvoiceStatus>(f.Status,true,out var status))q=q.Where(x=>x.Status==status);var total=await q.SumAsync(x=>(decimal?)x.GrandTotal)??0;var paid=await q.SumAsync(x=>(decimal?)x.PaidAmount)??0;var outstanding=await q.SumAsync(x=>(decimal?)x.OutstandingAmount)??0;var overdue=await q.Where(x=>x.Status==InvoiceStatus.Overdue).SumAsync(x=>(decimal?)x.OutstandingAmount)??0;var paidCount=await q.CountAsync(x=>x.Status==InvoiceStatus.Paid);var partial=await q.CountAsync(x=>x.Status==InvoiceStatus.PartiallyPaid);var paidInvoices=q.Where(x=>x.PaidAmount>0);var avgDays=await paidInvoices.Select(x=>(double?)EF.Functions.DateDiffDay(x.CreatedAt,x.UpdatedAt??x.CreatedAt)).AverageAsync()??0;m.Kpis=[Kpi("Total Invoiced",Money(m,total),"Invoice value","bi-receipt"),Kpi("Total Collected",Money(m,paid),"Paid amount","bi-wallet2","positive"),Kpi("Outstanding",Money(m,outstanding),"Open balance","bi-cash-stack","warning"),Kpi("Overdue",Money(m,overdue),"Past due exposure","bi-exclamation-triangle","warning"),Kpi("Paid Invoices",paidCount.ToString("N0"),"Settled invoices","bi-check-circle"),Kpi("Partially Paid",partial.ToString("N0"),"Open part-payments","bi-circle-half"),Kpi("Avg. Collection Time",$"{avgDays:N1} days","From creation to update","bi-clock-history")];m.TotalRecords=await q.CountAsync();var data=await q.OrderByDescending(x=>x.InvoiceDate).Skip((m.CurrentPage-1)*m.PageSize).Take(m.PageSize).Select(x=>new{Invoice=x.InvoiceNumber,Customer=x.Customer.FirstName+" "+x.Customer.LastName,x.InvoiceDate,x.DueDate,x.GrandTotal,x.PaidAmount,x.OutstandingAmount,x.Status,LastPayment=_db.Payments.Where(p=>p.InvoiceId==x.Id&&p.IsActive).Max(p=>(DateOnly?)p.PaymentDate),x.Id}).ToListAsync();var today=DateOnly.FromDateTime(DateTime.UtcNow);m.Columns=["Invoice","Customer","Invoice Date","Due Date","Total","Paid","Outstanding","Status","Last Payment","Days Overdue"];m.Rows=data.Select(x=>Row([x.Invoice,x.Customer,x.InvoiceDate.ToString("dd MMM yyyy"),x.DueDate.ToString("dd MMM yyyy"),Money(m,x.GrandTotal),Money(m,x.PaidAmount),Money(m,x.OutstandingAmount),x.Status.GetDisplayName(),x.LastPayment?.ToString("dd MMM yyyy")??"No payment",x.OutstandingAmount>0&&x.DueDate<today?$"{today.DayNumber-x.DueDate.DayNumber} days":"—"],x.Status.ToString(),Url.Action("Details","Invoices",new{id=x.Id}))).ToList();var statusData=await q.GroupBy(x=>x.Status).Select(g=>new{Name=g.Key.ToString(),Value=g.Count()}).ToListAsync();var methodData=await _db.Payments.AsNoTracking().Where(x=>x.PaymentDate>=m.RangeStart&&x.PaymentDate<=m.RangeEnd).GroupBy(x=>x.PaymentMethod).Select(g=>new{Name=g.Key.ToString(),Value=g.Sum(x=>x.Amount)}).ToListAsync();m.Charts=[Chart("invoiceStatuses","Invoice Status","Invoice workflow split","doughnut",statusData.Select(x=>x.Name),statusData.Select(x=>(decimal)x.Value)),Chart("paymentSplit","Payment Method Split","Collected amount by method","doughnut",methodData.Select(x=>x.Name),methodData.Select(x=>x.Value),true)];m.Insights=[Insight("Key finding",Money(m,paid),"Collected in selected period","bi-check2-circle"),Insight("Risk",Money(m,overdue),"Overdue amount requiring follow-up","bi-exclamation-triangle","risk"),Insight("Recommended action",$"{partial:N0} partial invoices","Prioritize open balances","bi-arrow-right-circle")];return Finish(m);
        }

