            var revenue = await q.SumAsync(x => (decimal?)x.PaidAmount) ?? 0;
            var duration = await q.AverageAsync(x => (double?)x.DurationMinutes) ?? 0;
            var peak = await q.GroupBy(x => x.StartTime.Hour).Select(g => new { Hour = g.Key, Count = g.Count() })
                .OrderByDescending(x => x.Count).FirstOrDefaultAsync();
            m.Kpis =
            [
                Kpi("Total Bookings", count.ToString("N0"), "Bookings in scope", "bi-calendar-check"),
                Kpi("Completed", completed.ToString("N0"), "Completed play", "bi-flag"),
                Kpi("Cancelled", cancelled.ToString("N0"), "Cancelled bookings", "bi-x-circle", "warning"),
                Kpi("No-shows", noShows.ToString("N0"), "Missed bookings", "bi-person-x", "warning"),
                Kpi("Booking Revenue", Money(m, revenue), "Paid booking value", "bi-cash-stack"),
                Kpi("Average Duration", $"{duration:N0} min", "Per booking", "bi-stopwatch"),
                Kpi("Peak Hour", peak == null ? "No data" : $"{peak.Hour:00}:00", "Most frequent start", "bi-clock")
            ];
            m.TotalRecords = count;
            var data = await q.OrderByDescending(x => x.BookingDate).ThenBy(x => x.StartTime)
                .Skip((m.CurrentPage - 1) * m.PageSize).Take(m.PageSize)
                .Select(x => new { x.Id, x.BookingNumber, Customer = x.Customer.FirstName + " " + x.Customer.LastName,
                    Sport = x.Sport.Name, Facility = x.Facility.Name, Court = x.Court.Name, x.BookingDate,
                    x.StartTime, x.EndTime, x.Status, x.Source, x.TotalAmount }).ToListAsync();
            m.Columns = ["Booking", "Customer", "Sport", "Facility", "Court", "Date", "Time", "Status", "Source", "Value"];
            m.Rows = data.Select(x => Row([x.BookingNumber, x.Customer, x.Sport, x.Facility, x.Court,
                x.BookingDate.ToString("dd MMM yyyy"), $"{x.StartTime:HH\\:mm}-{x.EndTime:HH\\:mm}",
                x.Status.GetDisplayName(), x.Source.GetDisplayName(), Money(m, x.TotalAmount)], x.Status.ToString(),
                Url.Action("Details", "Bookings", new { id = x.Id }))).ToList();
            var sports = await q.GroupBy(x => x.Sport.Name).Select(g => new { Name = g.Key, Value = g.Count() })
                .OrderByDescending(x => x.Value).Take(8).ToListAsync();
            var sources = await q.GroupBy(x => x.Source).Select(g => new { Name = g.Key.ToString(), Value = g.Count() }).ToListAsync();
            m.Charts =
            [
                Chart("bookingsSport", "Bookings by Sport", "Demand by sport", "bar", sports.Select(x => x.Name), sports.Select(x => (decimal)x.Value)),
                Chart("bookingSources", "Booking Sources", "Channel distribution", "doughnut", sources.Select(x => x.Name), sources.Select(x => (decimal)x.Value))
            ];
            m.Insights =
            [
                Insight("Key finding", peak == null ? "No peak hour" : $"{peak.Hour:00}:00 peak", "Most-booked start hour", "bi-clock"),
                Insight("Risk", $"{cancelled + noShows:N0} exceptions", "Cancelled and no-show bookings", "bi-exclamation-triangle", "risk"),
                Insight("Recommended action", $"{completed:N0} completed", "Compare demand with available hours", "bi-arrow-right-circle")
            ];
            return Finish(m);
        }

