nc(x=>(decimal?)x.PaidAmount)??0;m.Kpis=[Kpi("Facility Utilization",$"{utilization:N1}%","Overall booked capacity","bi-building"),Kpi("Court Utilization",$"{utilization:N1}%","Filtered courts","bi-grid-3x3-gap"),Kpi("Available Hours",$"{available:N0}","Scheduled capacity","bi-clock"),Kpi("Booked Hours",$"{bookedHours:N1}","Confirmed usage","bi-calendar-check"),Kpi("Unused Hours",$"{unused:N1}","Available opportunity","bi-hourglass","warning"),Kpi("Revenue per Court",Money(m,totalCourts==0?0:revenue/totalCourts),"Average collected value","bi-cash-stack"),Kpi("Revenue / Available Hour",Money(m,available<=0?0:revenue/(decimal)available),"Capacity productivity","bi-graph-up")];m.Columns=["Court","Sport","Facility","Available Hours","Booked Hours","Unused Hours","Utilization","Revenue","Revenue / Hour"];m.Rows=data.Select(x=>{var availableCourt=(decimal)(days*dailyHours);var booked=x.BookedMinutes/60m;var use=availableCourt<=0?0:Math.Min(100,booked/availableCourt*100);return Row([x.Court,x.Sport,x.Facility,$"{availableCourt:N1}",$"{booked:N1}",$"{Math.Max(0,availableCourt-booked):N1}",$"{use:N1}%",Money(m,x.Revenue),Money(m,availableCourt<=0?0:x.Revenue/availableCourt)],use<25?"Underutilized":"Active",Url.Action("CourtDetails","ArenaSetup",new{id=x.Id}));}).ToList();var chartData=data.OrderByDescending(x=>x.BookedMinutes).Take(10).ToList();m.Charts=[Chart("courtUtilization","Court Utilization","Booked hours by court","bar",chartData.Select(x=>x.Court),chartData.Select(x=>x.BookedMinutes/60m)),Chart("courtRevenue","Revenue by Court","Collected booking revenue","bar",chartData.Select(x=>x.Court),chartData.Select(x=>x.Revenue),true)];var under=data.Count(x=>x.BookedMinutes/60m<(decimal)(days*dailyHours)*.25m);var best=data.OrderByDescending(x=>x.Revenue).FirstOrDefault();m.Insights=[Insight("Most profitable court",best?.Court??"No data",best==null?"No revenue in scope":Money(m,best.Revenue),"bi-trophy"),Insight("Risk",$"{under:N0} underutilized","Below 25% utilization on this page","bi-exclamation-triangle","risk"),Insight("Recommended action",$"{unused:N1} unused hours","Promote off-peak inventory","bi-arrow-right-circle")];return Finish(m);
        }

        private async Task<ReportPageViewModel> RevenueReport(ReportPageViewModel m)
        {
            m.Title="Revenue Analysis";m.Description="Collected revenue trends, payment methods, customer contribution and daily performance.";m.ActionName=nameof(Revenue);var q=_db.Payments.AsNoTracking().Where(x=>x.IsActive&&x.PaymentDate>=m.RangeStart&&x.PaymentDate<=m.RangeEnd);if(m.Filter.CustomerId.HasValue)q=q.Where(x=>x.CustomerId==m.Filter.CustomerId);if(Enum.TryParse<InvoicePaymentMethod>(m.Filter.PaymentMethod,true,out var method))q=q.Where(x=>x.PaymentMethod==method);var total=await q.SumAsync(x=>(decimal?)x.Amount)??0;var count=await q.CountAsync();var avg=count==0?0:total/count;var highest=await q.MaxAsync(x=>(decimal?)x.Amount)??0;var invoiceCount=await q.Select(x=>x.InvoiceId).Distinct().CountAsync();m.Kpis=[Kpi("Collected Revenue",Money(m,total),"Recorded invoice payments","bi-wallet2","positive"),Kpi("Payments",count.ToString("N0"),"Transactions in scope","bi-credit-card"),Kpi("Average Payment",Money(m,avg),"Per transaction","bi-calculator"),Kpi("Highest Payment",Money(m,highest),"Largest transaction","bi-graph-up-arrow"),Kpi("Invoices Covered",invoiceCount.ToString("N0"),"Distinct invoices","bi-receipt")];m.TotalRecords=count;var data=await q.OrderByDescending(x=>x.PaymentDate).ThenByDescending(x=>x.CreatedAt).Skip((m.CurrentPage-1)*m.PageSize).Take(m.PageSize).Select(x=>new{x.Id,x.PaymentNumber,Invoice=x.Invoice.InvoiceNumber,Customer=x.Customer.FirstName+" "+x.Customer.LastName,x.PaymentDate,x.PaymentMethod,x.Amount,x.CurrencySymbol,Receiver=x.ReceivedByUser.FirstName+" "+x.ReceivedByUser.LastName,x.ReferenceNumber}).ToListAsync();m.Columns=["Payment","Invoice","Customer","Date","Method","Amount","Received By","Reference"];m.Rows=data.Select(x=>Row([x.PaymentNumber,x.Invoice,x.Customer,x.PaymentDate.ToString("dd MMM yyyy"),x.PaymentMethod.GetDisplayName(),Money(m,x.Amount),x.Receiver,x.ReferenceNumber??"—"],"Recorded",Url.Action("Details","Payments",new{id=x.Id}))).ToList();var trend=await q.GroupBy(x=>x.PaymentDate).Select(g=>new{Date=g.Key,Value=g.Sum(x=>x.Amount)}).OrderBy(x=>x.Date).ToListAsync();var methods=await q.GroupBy(x=>x.PaymentMethod).Select(g=>new{Name=g.Key.ToString(),Value=g.Sum(x=>x.Amount)}).OrderByDescending(x=>x.Value).ToListAsync();var customers=await q.GroupBy(x=>x.Customer.FirstName+" "+x.Customer.LastName).Select(g=>new{Name=g.Key,Value=g.Sum(x=>x.Amount)}).OrderByDescending(x=>x.Value).Take(8).ToListAsync();m.Charts=[Chart("revenueAnalysis","Revenue Trend","Collected amount by day","line",trend.Select(x=>x.Date.ToString("dd MMM")),trend.Select(x=>x.Value),true),Chart("revenueMethods","Payment Methods","Collection split","doughnut",methods.Select(x=>x.Name),methods.Select(x=>x.Value),true),Chart("topRevenueCustomers","Top Customers","Collected revenue contribution","bar",customers.Select(x=>x.Name),customers.Select(x=>x.Value),true)];var topMethod=methods.FirstOrDefault();m.Insights=[Insight("Key finding",topMethod?.Name??"No data",topMethod==null?"No payments in scope":Money(m,topMethod.Value),"bi-lightbulb"),Insight("Risk",$"{invoiceCount:N0} invoices covered","Compare with outstanding receivables","bi-exclamation-triangle","risk"),Insight("Recommended action",Money(m,avg),"Monitor average payment value","bi-arrow-right-circle")];return Finish(m);
        }

        private async Task<ReportPageViewModel> BasePage(string report, ReportFilterViewModel filter)
        {
            filter.PageSize=PageSizes.Contains(filter.PageSize)?filter.PageSize:10;filter.Page=Math.Max(1,filter.Page);var range=ResolveRange(filter);await ValidateIds(filter);var settings=await Settings();return new ReportPageViewModel{ReportKey=report,ActionName=report,Filter=filter,Options=await Options(),Currency=settings.Currency,CurrencySymbol=settings.CurrencySymbol??"Rs",ArenaName=settings.ArenaName,TimeZoneLabel="Pakistan Standard Time",RefreshedAt=PakistanNow(),RangeStart=range.Start,RangeEnd=range.End,CurrentPage=filter.Page,PageSize=filter.PageSize,ShowFinancials=CanSeeFinancials(),FilterSummary=FilterSummary(filter,range.Start,range.End)};
        }

        private async Task ValidateIds(ReportFilterViewModel f)
        {
            if(f.SportId.HasValue&&!await _db.Sports.AsNoTracking().AnyAsync(x=>x.Id==f.SportId)){ModelState.AddModelError(nameof(f.SportId),"Invalid sport filter.");f.SportId=null;}if(f.FacilityId.HasValue&&!await _db.Facilities.AsNoTracking().AnyAsync(x=>x.Id==f.FacilityId)){ModelState.AddModelError(nameof(f.FacilityId),"Invalid facility filter.");f.FacilityId=null;}if(f.CourtId.HasValue&&!await _db.Courts.AsNoTracking().AnyAsync(x=>x.Id==f.CourtId)){ModelState.AddModelError(nameof(f.CourtId),"Invalid court filter.");f.CourtId=null;}if(f.CustomerId.HasValue&&!await _db.Customers.AsNoTracking().AnyAsync(x=>x.Id==f.CustomerId)){ModelState.AddModelError(nameof(f.CustomerId),"Invalid customer filter.");f.CustomerId=null;}if(f.OwnerId.HasValue&&!await _db.Users.AsNoTracking().AnyAsync(x=>x.Id==f.OwnerId)){ModelState.AddModelError(nameof(f.OwnerId),"Invalid owner filter.");f.OwnerId=null;}
        }

        private (DateOnly Start,DateOnly End) ResolveRange(ReportFilterViewModel f)
        {
            var today=DateOnly.FromDateTime(PakistanNow());DateOnly start,end;switch((f.Preset??"").ToLowerInvariant()){case"today":start=end=today;break;case"yesterday":start=end=today.AddDays(-1);break;case"this-week":start=today.AddDays(-(((int)today.DayOfWeek+6)%7));end=today;break;case"last-month":var first=new DateOnly(today.Year,today.Month,1);end=first.AddDays(-1);start=new DateOnly(end.Year,end.Month,1);break;case"this-quarter":var month=((today.Month-1)/3)*3+1;start=new DateOnly(today.Year,month,1);end=today;break;case"this-year":start=new DateOnly(today.Year,1,1);end=today;break;case"custom":start=f.StartDate??today.AddDays(-30);end=f.EndDate??today;if(!f.StartDate.HasValue||!f.EndDate.HasValue)ModelState.AddModelError(string.Empty,"Choose both start and end dates for a custom range.");break;default:start=new DateOnly(today.Year,today.Month,1);end=today;f.Preset="this-month";break;}if(end<start){ModelState.AddModelError(string.Empty,"End date cannot be before start date.");end=start;}if(end.DayNumber-start.DayNumber>1825){ModelState.AddModelError(string.Empty,"Report ranges cannot exceed five years.");start=end.AddYears(-5);}f.StartDate=start;f.EndDate=end;return(start,end);
        }

        private IQueryable<Booking> ApplyBookingFilters(IQueryable<Booking> q,ReportFilterViewModel f){if(f.SportId.HasValue)q=q.Where(x=>x.SportId==f.SportId);if(f.FacilityId.HasValue)q=q.Where(x=>x.FacilityId==f.FacilityId);if(f.CourtId.HasValue)q=q.Where(x=>x.CourtId==f.CourtId);if(f.CustomerId.HasValue)q=q.Where(x=>x.CustomerId==f.CustomerId);return q;}
        private async Task<ReportFilterOptionsViewModel> Options()=>new(){Sports=await _db.Sports.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(),Facilities=await _db.Facilities.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(),Courts=await _db.Courts.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(),Customers=await _db.Customers.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.FirstName).Select(x=>new SelectListItem(x.FirstName+" "+x.LastName,x.Id.ToString())).Take(250).ToListAsync(),Owners=await _db.Users.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.FirstName).Select(x=>new SelectListItem(x.FirstName+" "+x.LastName,x.Id.ToString())).ToListAsync()};
        private ReportPageViewModel Finish(ReportPageViewModel m){m.TotalPages=Math.Max(1,(int)Math.Ceiling(m.TotalRecords/(double)m.PageSize));m.CurrentPage=Math.Min(m.CurrentPage,m.TotalPages);return m;}
        private async Task<ReportChartViewModel> StatusChart(IQueryable<SalesQuotation> q,string id,string title,string subtitle){var data=await q.GroupBy(x=>x.Status).Select(g=>new{Name=g.Key.ToString(),Value=g.Count()}).ToListAsync();return Chart(id,title,subtitle,"doughnut",data.Select(x=>x.Name),data.Select(x=>(decimal)x.Value));}
        private static ReportKpiViewModel Kpi(string label,string value,string helper,string icon,string tone="")=>new(){Label=label,Value=value,Helper=helper,Icon=icon,Tone=tone};
        private static ReportInsightViewModel Insight(string label,string value,string detail,string icon,string tone="")=>new(){Label=label,Value=value,Detail=detail,Icon=icon,Tone=tone};
        private static ReportChartViewModel Chart(string id,string title,string subtitle,string type,IEnumerable<string> labels,IEnumerable<decimal> values,bool currency=false)=>new(){Id=id,Title=title,Subtitle=subtitle,Type=type,Labels=labels.ToList(),Values=values.ToList(),Currency=currency,Colors=["#d6a652","#171614","#4f8b6d","#c77b4f","#7b8494","#ead09a","#8e6640","#9d4f4f"]};
        private static ReportTableRowViewModel Row(IReadOnlyList<string> cells,string? status=null,string? url=null)=>new(){Cells=cells,Status=status,DetailUrl=url};
        private static string Percent(int value,int total)=>total==0?"0.0%":$"{value*100m/total:N1}%";
        private static string Money(ReportPageViewModel m,decimal value)=>$"{m.CurrencySymbol} {value:N2}";
        private static string FilterSummary(ReportFilterViewModel f,DateOnly start,DateOnly end)=>$"{start:dd MMM yyyy} to {end:dd MMM yyyy}"+(f.SportId.HasValue?" · Sport filtered":"")+(f.FacilityId.HasValue?" · Facility filtered":"")+(f.CustomerId.HasValue?" · Customer filtered":"");
        private static DateTime PakistanNow(){try{return TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Pakistan Standard Time"));}catch{return DateTime.UtcNow.AddHours(5);}}
        private async Task<SystemSettings> Settings()=>await _db.SystemSettings.AsNoTracking().FirstOrDefaultAsync()??new SystemSettings{ArenaName="GameHub Arena",Currency="PKR",CurrencySymbol="Rs"};
        private bool CanSeeFinancials()=>RolePermissions.TryGetCurrentRole(User,out var r)&&r is UserRole.SuperAdmin or UserRole.Admin or UserRole.FinanceManager;
        private bool CanAccessReport(string report){if(!RolePermissions.TryGetCurrentRole(User,out var r))return false;if(r is UserRole.SuperAdmin or UserRole.Admin)return true;return report switch{"sales" or "invoices" or "revenue" or "exports"=>r==UserRole.FinanceManager,"bookings" or "utilization"=>r is UserRole.BookingManager or UserRole.CourtManager or UserRole.Receptionist or UserRole.Viewer,"customers" or "memberships"=>r is UserRole.BookingManager or UserRole.Receptionist or UserRole.FinanceManager or UserRole.StaffManager or UserRole.Viewer,"crm"=>r is UserRole.BookingManager or UserRole.Receptionist,"overview"=>true,_=>false};}
        private IReadOnlyList<ReportModuleLinkViewModel> Modules()=>[new(){Title="Sales Report",Description="Quotation and order conversion",Action=nameof(Sales),Icon="bi-graph-up-arrow",Available=CanAccessReport("sales")},new(){Title="Invoices & Payments",Description="Receivables and collections",Action=nameof(Invoices),Icon="bi-receipt",Available=CanAccessReport("invoices")},new(){Title="Booking Report",Description="Volume, demand and revenue",Action=nameof(Bookings),Icon="bi-calendar-check",Available=CanAccessReport("bookings")},new(){Title="Customer Report",Description="Growth, value and loyalty",Action=nameof(Customers),Icon="bi-people",Available=CanAccessReport("customers")},new(){Title="Membership Report",Description="Subscriptions and retention",Action=nameof(Memberships),Icon="bi-person-badge",Available=CanAccessReport("memberships")},new(){Title="CRM Performance",Description="Leads and opportunities",Action=nameof(CRM),Icon="bi-funnel",Available=CanAccessReport("crm")},new(){Title="Utilization Report",Description="Facility and court productivity",Action=nameof(Utilization),Icon="bi-grid-3x3-gap",Available=CanAccessReport("utilization")},new(){Title="Revenue Analysis",Description="Collection trends and methods",Action=nameof(Revenue),Icon="bi-cash-stack",Available=CanAccessReport("revenue")},new(){Title="Export Center",Description="Filtered report downloads",Action=nameof(Exports),Icon="bi-download",Available=CanAccessReport("exports")}];
        private FileContentResult Csv(ReportPageViewModel m,string generatedBy){var b=new StringBuilder();b.AppendLine(CsvLine([m.ArenaName,m.Title]));b.AppendLine(CsvLine(["Generated",m.RefreshedAt.ToString("dd MMM yyyy HH:mm"),"Generated By",generatedBy]));b.AppendLine(CsvLine(["Filters",m.FilterSummary,"Currency",m.Currency]));b.AppendLine();b.AppendLine(CsvLine(m.Columns));foreach(var row in m.Rows)b.AppendLine(CsvLine(row.Cells));return File(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(b.ToString())).ToArray(),"text/csv",$"GameHub-{m.ReportKey}-{DateTime.UtcNow:yyyyMMdd}.csv");}
        private FileContentResult Excel(ReportPageViewModel m,string generatedBy){var b=new StringBuilder();b.Append("<html><head><meta charset='utf-8'></head><body>");b.Append($"<h1>{System.Net.WebUtility.HtmlEncode(m.ArenaName)} - {System.Net.WebUtility.HtmlEncode(m.Title)}</h1><p>Generated {m.RefreshedAt:dd MMM yyyy HH:mm} by {System.Net.WebUtility.HtmlEncode(generatedBy)}<br>{System.Net.WebUtility.HtmlEncode(m.FilterSummary)} · Currency {System.Net.WebUtility.HtmlEncode(m.Currency)}</p><table border='1'><thead><tr>");foreach(var c in m.Columns)b.Append($"<th>{System.Net.WebUtility.HtmlEncode(c)}</th>");b.Append("</tr></thead><tbody>");foreach(var row in m.Rows){b.Append("<tr>");foreach(var c in row.Cells)b.Append($"<td>{System.Net.WebUtility.HtmlEncode(c)}</td>");b.Append("</tr>");}b.Append("</tbody></table></body></html>");return File(Encoding.UTF8.GetBytes(b.ToString()),"application/vnd.ms-excel",$"GameHub-{m.ReportKey}-{DateTime.UtcNow:yyyyMMdd}.xls");}
        private static string CsvLine(IEnumerable<string> cells)=>string.Join(",",cells.Select(x=>$"\"{(x??string.Empty).Replace("\"","\"\"")}\""));

